const JP_TO_ZH={'稲':'稻','浅':'淺','桜':'櫻','竜':'龍','国':'國','沢':'澤','広':'廣','円':'圓','実':'實','徳':'德','関':'關','応':'應','観':'觀','辺':'邊','弁':'辨','寿':'壽','専':'專','済':'濟','来':'來','亀':'龜','浜':'濱','気':'氣','学':'學','鉄':'鐵','栄':'榮','仏':'佛','当':'當','総':'總','区':'區'};
