function todayLocal(){const now=new Date(),offset=now.getTimezoneOffset()*60000;return new Date(now-offset).toISOString().slice(0,10)}
function addDaysLocal(dateText,days){const date=new Date(`${dateText}T12:00:00`);date.setDate(date.getDate()+days);return date.toISOString().slice(0,10)}
