function openPhotoDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open('tabi-goshuin',1);request.onupgradeneeded=()=>request.result.createObjectStore('photos');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
