function findPlaceForStop(stop){const names=[stop[0],stop[1]].filter(Boolean);return SHRINE_PLACES.find(place=>names.some(name=>`${place.name} ${place.nameJa}`.includes(name)||name.includes(place.nameJa||'__')))}
function togglePilgrimageSeries(id){const series=PILGRIMAGE_SERIES.find(item=>item.id===id);if(!series)return;const matches=series.stops.map(findPlaceForStop).filter(Boolean);if(state.selectedSeries.has(id)){state.selectedSeries.delete(id);matches.forEach(place=>state.selected.delete(place.id))}else{state.selectedSeries.add(id);matches.forEach(place=>state.selected.add(place.id))}persistCollections();renderCandidates();openPilgrimageModal(id)}

