  const explicitFood=request.themes.includes('food'),maxFood=request.singleMeal?1:(explicitFood?2:1),foods=candidates.filter(isFoodPlace).slice(0,maxFood),nightPlaces=candidates.filter(place=>place.category==='展望夜景').slice(0,1),nonFoods=candidates.filter(place=>!isFoodPlace(place)&&place.category!=='展望夜景').slice(0,Math.max(0,count-foods.length-nightPlaces.length));
