function buildStructuredItinerary(){return{tripDays:state.tripDates.length,days:state.tripDates.map((date,index)=>{const items=state.itinerary[index]||[],setting=state.daySettings[date]||{start:state.dayStart,end:state.dayEnd};return{dayNumber:index+1,date,title:dayAreaLabel(items)||`Day ${index+1}`,dayType:'full',items:items.map((place,itemIndex)=>structuredItem(place,items[itemIndex-1])),startTime:setting.start,endTime:setting.end}})}}
