function escapeMapText(value=''){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function mapFilteredPlaces(){const q=state.mapSearch.trim().toLowerCase(),tripIds=new Set(state.itinerary.flat().map(place=>place.id));return SHRINE_PLACES.filter(place=>{const matchesSearch=!q||`${place.name} ${place.nameJa||''} ${place.nameEn||''} ${place.area} ${(place.tags||[]).join(' ')}`.toLowerCase().includes(q);const matchesState=state.mapFilter==='all'||(state.mapFilter==='visited'&&state.visited.has(place.id))||(state.mapFilter==='unvisited'&&!state.visited.has(place.id))||(state.mapFilter==='trip'&&tripIds.has(place.id));return matchesSearch&&matchesState}).sort((a,b)=>(Number(b.completionScore)-Number(a.completionScore))||(b.popularity-a.popularity))}
function markerPopup(place){const visited=state.visited.has(place.id);return `<div class="map-popup"><b>${visited?'✓ ':''}${escapeMapText(displayName(place))}</b><small>${escapeMapText(place.nameJa||place.nameEn||'')}</small><span>${escapeMapText(place.area)} · ${placeKind(place)==='shrine'?'神社':'寺院'}${visited?' · 已參拜':''}</span><button data-map-detail="${escapeMapText(place.id)}">查看／記錄御朱印</button></div>`}
function renderMapList(){const places=mapFilteredPlaces();$('#mapPlaceTotal').textContent=SHRINE_PLACES.length.toLocaleString();$('#mapResultCount').textContent=`${places.length.toLocaleString()} 間已驗證寺社`;$('#mapPlaceList').innerHTML=places.slice(0,200).map(place=>`<button class="map-place-item ${state.visited.has(place.id)?'visited':''}" data-map-place="${place.id}"><span>${placeKind(place)==='shrine'?'⛩':'卍'}</span><div><b>${escapeMapText(displayName(place))}</b><small>${escapeMapText(place.area)} · ${placeKind(place)==='shrine'?'神社':'寺院'}${state.visited.has(place.id)?' · 已參拜':''}</small></div><em>${state.visited.has(place.id)?'✓':'資料 '+place.completionScore+'%'}</em></button>`).join('')||'<p class="map-empty">找不到符合條件的寺社。</p>';$$('[data-map-place]').forEach(button=>button.onclick=()=>focusMapPlace(button.dataset.mapPlace))}
function renderMapMarkers(){if(!shrineMap)return;const visibleIds=new Set(mapFilteredPlaces().map(place=>place.id));for(const [id,marker] of mapMarkers){if(visibleIds.has(id)){if(!shrineMap.hasLayer(marker))marker.addTo(shrineMap)}else if(shrineMap.hasLayer(marker))marker.removeFrom(shrineMap)}renderMapList()}
function templeMarkerIcon(place){const shrine=placeKind(place)==='shrine',visited=state.visited.has(place.id);return L.divIcon({className:'temple-marker-wrap',html:`<div class="temple-marker ${shrine?'shrine':'temple'} ${visited?'visited':''}"><span>${visited?'✓':(shrine?'⛩':'卍')}</span></div>`,iconSize:[38,44],iconAnchor:[19,42],popupAnchor:[0,-38]})}
function initShrineMap(){if(shrineMap||typeof L==='undefined')return;shrineMap=L.map('shrineMap',{zoomControl:true,minZoom:5}).setView([35.6812,139.7671],10);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(shrineMap);SHRINE_PLACES.forEach(place=>{const marker=L.marker([place.lat,place.lng],{title:displayName(place),icon:templeMarkerIcon(place)}).bindPopup(markerPopup(place));marker.on('popupopen',()=>setTimeout(()=>{$$('[data-map-detail]').forEach(button=>button.onclick=()=>openPlaceModal(button.dataset.mapDetail))},0));mapMarkers.set(place.id,marker);marker.addTo(shrineMap)});renderMapList();fitAllShrines()}
function refreshMapMarkers(){for(const place of SHRINE_PLACES){const marker=mapMarkers.get(place.id);if(marker){marker.setIcon(templeMarkerIcon(place));marker.setPopupContent(markerPopup(place))}}if(shrineMap)renderMapList()}
function focusMapPlace(id){initShrineMap();const place=byId(id),marker=mapMarkers.get(id);if(!place||!marker)return;shrineMap.setView([place.lat,place.lng],16,{animate:true});marker.openPopup()}
function showPlaceOnMap(id){switchView('map');requestAnimationFrame(()=>focusMapPlace(id))}
function fitAllShrines(){initShrineMap();const visible=mapFilteredPlaces().map(place=>[place.lat,place.lng]);if(visible.length)shrineMap.fitBounds(visible,{padding:[24,24],maxZoom:12})}
$('#mapSearch').addEventListener('input',event=>{state.mapSearch=event.target.value;renderMapMarkers()});
$$('[data-map-filter]').forEach(button=>button.onclick=()=>{$$('[data-map-filter]').forEach(item=>item.classList.remove('active'));button.classList.add('active');state.mapFilter=button.dataset.mapFilter;renderMapMarkers();fitAllShrines()});
$('#fitMapButton').onclick=fitAllShrines;
$('#locateMeButton').onclick=()=>{if(!navigator.geolocation){alert('此裝置不支援定位。');return}navigator.geolocation.getCurrentPosition(position=>{initShrineMap();const latlng=[position.coords.latitude,position.coords.longitude];if(userLocationMarker)userLocationMarker.remove();userLocationMarker=L.circleMarker(latlng,{radius:9,color:'#174c3d',fillColor:'#d8ef9c',fillOpacity:1}).addTo(shrineMap).bindPopup('你目前的位置').openPopup();shrineMap.setView(latlng,14)},()=>alert('無法取得位置，請在 iPhone 瀏覽器允許定位權限。'),{enableHighAccuracy:true,timeout:10000})};
