const initialDate=todayLocal(),savedUnified=storedTripDraft?.normalizedTripRequirements||storedRequirements;$('#tripStartDate').value=savedUnified?.fields?.dates?.value?.start||initialDate;$('#tripEndDate').value=savedUnified?.fields?.dates?.value?.end||addDaysLocal(initialDate,5);if(savedUnified){state.normalizedTripRequirements=savedUnified;syncFormFromRequirements()}if(storedTripDraft?.itinerary?.length){state.itinerary=storedTripDraft.itinerary.map(day=>day.map(byId).filter(Boolean));state.tripDates=storedTripDraft.tripDates||[];state.dayStart=storedTripDraft.dayStart||'09:00';state.dayEnd=storedTripDraft.dayEnd||'22:00';state.preferences=storedTripDraft.preferences||[];state.request={unsupported:[],normalizedTripRequirements:TripRequirementsState.plain(state.normalizedTripRequirements)}}renderFeatured();renderFilters();renderPlaces();renderPilgrimageGuides();renderCandidates();renderCollectionBook();updateHolidayNotice();if(state.itinerary.length){renderTrip();switchView('planner')}
